    @overload
    def tokenize(self, value: bytes) -> Token: ***REDACTED***
    @overload
    def tokenize(self, value: int) -> Token: ***REDACTED***
    @overload
    def tokenize(self, value: float) -> Token: ***REDACTED***
    @overload
