    ISO_FORMAT = "%Y-%m-%dT%H:%M:%S"
    DATE_FORMAT = "%Y-%m-%d"

    def __init__(self, format_str: str | None = None) -> None:
        self.format_str = format_str

    def tokenize(self, value: datetime | date) -> Token:
        if self.format_str:
