    maxLength match {
      case Some(max) if processed.length > max => Some(processed.take(max))
      case _ => if (processed.isEmpty) None else Some(processed)
    }
  }

  def tokenize(text: String): List[Token] = {
    text.split("\\s+").filter(_.nonEmpty).toList.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }
  }
}

class TokenizerBuilder[T] {
  private var _normalizers: List[String => String] = Nil
  private var _validators: List[T => Boolean] = Nil
  private var _metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    _normalizers = _normalizers :+ normalizer
